static SPEEX_NB3_STAGE_O2 uint16_t speex_nb3_unpack_subframe(const uint8_t *p,uint8_t offset,uint8_t indices[4])
{
    const uint8_t a=p[0],b=p[1],c=p[2],d=p[3],e=p[4];
    switch(offset) {
    case 4:
        indices[0]=(c>>2)&31;
