#include "nb3_indices.h"
/* Mode 3 has four unsigned 5-bit codebook indices, ten samples each.
 * Fuse the original split_cb_shape_sign_unquant + signal_mul operations:
 * (shape << 9) >> 7 == shape * 4, including negative signed shapes. */
#include "zero_innovation.h"
_Static_assert(SIG_SHIFT==14,"NB3 excitation rounding requires Q14");
extern const signed char exc_10_32_table[];
/* Zero adaptive gain only; no pitch data or temporary buffer is needed. */
#if SPEEX_NB3_USE_AVR_ASM
static
#else
static SPEEX_NB3_STAGE
#endif
void speex_nb3_zero_innovation(spx_word16_t *out,
                                    const uint8_t *input_indices,spx_word32_t scale)
{
#if SPEEX_NB3_USE_AVR_ASM
    const uint8_t *indices=input_indices;
#else
    uint8_t indices[4];
    for(unsigned k=0;k<4;k++)indices[k]=input_indices[k];
#endif
    int vector, sample;
    for (vector = 0; vector < 4; ++vector) {
        unsigned index = indices[vector];
        const signed char *shape = exc_10_32_table + 10*index;
#if SPEEX_NB3_USE_AVR_ASM
        speex_avr_zero_innovation10(out,shape,scale);
        out+=10;
#else
        for (sample = 0; sample < 10; ++sample)
            *out++=speex_nb3_zero_shape_c(AVR_READ_I8(shape+sample),scale);
#endif
    }
}

sourceText.14d09f73ba3d02e26ee2ef232b7a9cf628302d8e:
/* Private NB3 packet map: 5 mode bits, 18 LSP bits, 5 frame-gain bits,
 * then four 33-bit groups: pitch(7), adaptive gain(5), energy(1), indices(20).
 * Call only after validating a complete 20-byte NB mode-3 packet, with
 * sub in 0..3 and four writable index bytes disjoint from that packet.
 * The window begins at byte 3+4*sub / bit 4+sub and ends within byte 19.
 * This is a C-only bounded packet reader, not a generic SpeexBits API.
 * Keep generic partial-read/overflow helpers separate from this trusted map. */
#ifndef SPEEX_NB3_SUBFRAME_H
#define SPEEX_NB3_SUBFRAME_H
#include "speex_platform.h"

static SPEEX_NB3_STAGE_O2 uint16_t speex_nb3_unpack_subframe(
    const uint8_t *packet, uint8_t sub, uint8_t indices[4])
{
    const uint8_t *p=packet+3+4*sub;
    const uint8_t a=p[0],b=p[1],c=p[2],d=p[3],e=p[4];
    switch (sub) {
    case 0:
        indices[0]=(c>>2)&31;
        indices[1]=((c&3)<<3)|(d>>5);
